-- Create a temporary table with unique projectId-tagId pairs
CREATE TEMPORARY TABLE temp_unique_tags AS
SELECT MIN(CONCAT(projectId, '-', tagId)) as keep_key, projectId, tagId
FROM projectTags
GROUP BY projectId, tagId;

-- Delete all from projectTags
DELETE FROM projectTags;

-- Re-insert unique pairs
INSERT INTO projectTags (projectId, tagId)
SELECT projectId, tagId FROM temp_unique_tags;

-- Drop temp table
DROP TEMPORARY TABLE temp_unique_tags;

